import { useState } from 'react';

function Home({ onSearch, darkMode }) {
  const [input, setInput] = useState('AAPL');

  const handleSearch = () => {
    if (input.trim()) {
      onSearch(input.toUpperCase());
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <div style={{ 
      padding: '100px 20px', 
      textAlign: 'center',
      minHeight: '80vh',
      background: darkMode ? '#0f172a' : '#ffffff',
      color: darkMode ? '#f1f5f9' : '#0f172a'
    }}>
      <h1 style={{ 
        fontSize: '24px', 
        fontWeight: '600',
        marginBottom: '20px'
      }}>
        StockVision Home
      </h1>
      
      <div style={{ 
        display: 'flex', 
        justifyContent: 'center', 
        gap: '8px',
        alignItems: 'center'
      }}>
        <input 
          type="text"
          value={input} 
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder="Enter symbol"
          style={{
            padding: '4px 8px',
            border: '1px solid #ccc',
            fontSize: '14px',
            width: '150px'
          }}
        />
        <button 
          onClick={handleSearch}
          style={{
            padding: '4px 12px',
            border: '1px solid #ccc',
            background: '#f5f5f5',
            cursor: 'pointer',
            fontSize: '14px'
          }}
        >
          Search
        </button>
        <button 
          onClick={() => onSearch('AAPL')}
          style={{
            padding: '4px 12px',
            border: '1px solid #ccc',
            background: '#f5f5f5',
            cursor: 'pointer',
            fontSize: '14px'
          }}
        >
          Demo AAPL
        </button>
      </div>
    </div>
  );
}

export default Home;